<section class="student-tool-workspace"><form method="post" class="student-form-grid" data-saved-preparation-form><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-preparations'))?>"><input type="hidden" name="action" value="create"><label class="form-field student-span-2">Nome do preparo<input name="label" required placeholder="Ex.: Parodinal que uso normalmente"></label><label class="form-field student-span-2">Revelador<select name="developer_key" data-developer-select><?php foreach($developers as $key=>$developer):?><option value="<?=h($key)?>" data-preparation-mode="<?=h((string)$developer['mode'])?>"><?=h((string)$developer['label'])?></option><?php endforeach;?></select></label><label class="form-field student-span-2" data-custom-developer hidden>Nome do revelador<input name="developer_name"></label><div class="student-span-2 student-developer-mix" data-developer-mix><div class="student-form-grid"><label class="form-field">Revelador / solução estoque (ml)<input type="number" min="0" step="0.1" name="developer_amount" data-developer-amount></label><label class="form-field">Água (ml)<input type="number" min="0" step="0.1" name="water_amount" data-water-amount></label><output class="student-dilution-output student-span-2" data-dilution-output></output></div></div><div class="student-span-2 student-caffenol-prep" data-fresh-preparation hidden><div class="student-form-grid"><label class="form-field">Café (g)<input type="number" min="0" step="0.1" name="coffee_amount"></label><label class="form-field">Carbonato (g)<input type="number" min="0" step="0.1" name="carbonate_amount"></label><label class="form-field">Ácido ascórbico (g)<input type="number" min="0" step="0.1" name="ascorbic_amount"></label><label class="form-field">Volume preparado (ml)<input type="number" min="0" step="1" name="fresh_volume"></label></div></div><label class="form-field">Temperatura<input name="temperature"></label><label class="form-field">Tempo<input name="duration"></label><label class="form-field student-span-2">Agitação<input name="agitation"></label><div class="student-actions student-span-2"><button class="button button-primary" type="submit">Salvar preparo</button></div></form></section>
<section class="student-section"><div class="student-section-heading"><div><p class="student-kicker">Seus preparos</p><h2 class="student-subtitle"><?=count($rows)?> salvo(s)</h2></div></div><?php if(!$rows):?><div class="student-empty">Nenhum preparo salvo.</div><?php else:?><div class="student-test-list"><?php foreach($rows as $row):$calc=student_process_dilution($row['developer_amount']!==null?(float)$row['developer_amount']:null,$row['water_amount']!==null?(float)$row['water_amount']:null,(string)$row['preparation_mode']);?><article class="student-simple-row"><div><span class="student-status"><?=h((string)$row['developer_name'])?></span><h3><?=h((string)$row['label'])?></h3><p><?=h(implode(' · ',array_filter([$calc['label'],(string)$row['temperature'],(string)$row['duration']])))?></p></div><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-preparations'))?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="student-link student-danger-link" type="submit">remover</button></form></article><?php endforeach;?></div><?php endif;?></section><?php student_shell_end();